"use client";

import * as React from "react";
import {
  ListFilter,
  X,
  Search,
  Type,
  Hash,
  Calendar,
  ToggleLeft,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { FilterRow } from "./filter-row";
import { FilterValueSelector } from "./filter-value-selector";
import { FilterOperatorSelector } from "./filter-operator-selector";
import { FilterDateValue } from "./filter-date-value";
import { FilterBooleanValue } from "./filter-boolean-value";
import {
  type QueryFilter,
  type FilterValue,
  type FilterType,
  getDefaultOperator,
  defineDefaultFilterValue,
  operatorSupportsMultipleValues,
  operatorRequiresValue,
  operatorIsBetween,
} from "../../lib/filter-utils";
import {
  type FieldPath,
  type Filter,
  type FilterOperator,
  type FilterValueFor,
  type OperatorsForType,
  isValidOperatorForType,
} from "@woltz/rich-domain";
import type { UseCriteriaReturn } from "@/types/use-criteria.type";
import { cn } from "@/lib/utils";
import { useDebounceCallback } from "@/hooks/use-debounce-callback";

interface FilterProps {
  fields: QueryFilter[];
  filters: Filter<string, unknown>[];
  addOrReplaceByIndex: UseCriteriaReturn<unknown>["addOrReplaceByIndex"];
  removeFilter: (index: number) => void;
  clearFilters: () => void;
}

const TYPE_ICONS: Record<FilterType, React.ReactNode> = {
  string: <Type className="h-4 w-4" />,
  number: <Hash className="h-4 w-4" />,
  date: <Calendar className="h-4 w-4" />,
  boolean: <ToggleLeft className="h-4 w-4" />,
};

export function Filter({
  fields,
  filters,
  addOrReplaceByIndex,
  removeFilter,
  clearFilters,
}: FilterProps) {
  const [addFilterStep, setAddFilterStep] = React.useState<
    null | "field" | "value"
  >(null);
  const [search, setSearch] = React.useState("");
  const [selectedFieldForAdd, setSelectedFieldForAdd] =
    React.useState<QueryFilter | null>(null);
  const [tempOperator, setTempOperator] =
    React.useState<FilterValue["operator"]>("equals");
  const [tempValue, setTempValue] = React.useState<FilterValue["value"]>(null);

  const filterValues: FilterValue[] = filters.map((filter) => ({
    field: filter.field,
    operator: filter.operator as FilterValue["operator"],
    value: filter.value as FilterValue["value"],
  }));

  const usedFields = filters.map((filter) => filter.field);
  const remainingFields = fields.filter(
    (field) => !usedFields.includes(field.field)
  );

  const HAS_FIELDS_REMAINING = remainingFields.length > 0;

  const filteredRemainingFields = remainingFields.filter((field) =>
    field.fieldLabel.toLowerCase().includes(search.toLowerCase())
  );

  const handleSelectFieldForAdd = (field: QueryFilter) => {
    setSelectedFieldForAdd(field);
    const defaultOp = getDefaultOperator(field.type);
    setTempOperator(defaultOp);
    const defaultValue = operatorIsBetween(defaultOp)
      ? field.type === "number"
        ? [0, 0]
        : ["", ""]
      : defineDefaultFilterValue(field.type, defaultOp);
    setTempValue(defaultValue);
    setSearch("");
    setAddFilterStep("value");
  };

  const handleConfirmAddFilter = () => {
    if (!selectedFieldForAdd || tempValue === null) return;

    addOrReplaceByIndex({
      field: selectedFieldForAdd.field as FieldPath<unknown>,
      operator: tempOperator as OperatorsForType<never>,
      value: tempValue as FilterValueFor<never>,
      options: selectedFieldForAdd.isCollection
        ? { quantifier: "some" }
        : undefined,
    });

    setAddFilterStep(null);
    setSelectedFieldForAdd(null);
    setTempOperator("equals");
    setTempValue(null);
  };

  const handleCancelAddFilter = () => {
    setAddFilterStep(null);
    setSelectedFieldForAdd(null);
    setTempOperator("equals");
    setTempValue(null);
    setSearch("");
  };

  const handleUpdateFilter = (index: number, newValue: FilterValue) => {
    const prevFilter = filterValues[index];
    if (!prevFilter) return;

    const newField = fields.find((f) => f.field === newValue.field);
    const prevField = fields.find((f) => f.field === prevFilter.field);
    if (!newField || !prevField) return;

    const fieldTypeChanged = prevField.type !== newField.type;

    const operator = fieldTypeChanged
      ? getDefaultOperator(newField.type)
      : newValue.operator;

    let value =
      newValue.value === null || fieldTypeChanged
        ? defineDefaultFilterValue(newField.type, newValue.operator)
        : newValue.value;

    const newOperatorIsArrayOperator = operatorSupportsMultipleValues(operator);
    const prevOperatorIsArrayOperator = operatorSupportsMultipleValues(
      prevFilter.operator
    );
    const newOperatorIsBetween = operatorIsBetween(operator);
    const prevOperatorIsBetween = operatorIsBetween(prevFilter.operator);

    if (prevOperatorIsArrayOperator && !newOperatorIsArrayOperator) {
      value = null;
    }

    if (prevOperatorIsBetween && !newOperatorIsBetween) {
      value = null;
    } else if (!prevOperatorIsBetween && newOperatorIsBetween) {
      value = newField.type === "number" ? [0, 0] : ["", ""];
    }

    addOrReplaceByIndex({
      field: newField.field as FieldPath<unknown>,
      operator: operator as OperatorsForType<never>,
      value: value as FilterValueFor<never>,
      options: newField.isCollection ? { quantifier: "some" } : undefined,
      replaceIndex: index,
    });
  };

  const [handleUpdateFilterDebounced] = useDebounceCallback(
    (index: number, newValue: FilterValue) => {
      handleUpdateFilter(index, newValue);
    },
    300
  );

  const handleSelectField = (index: number, newValue: FilterValue) => {
    const filterToUpdate = filters[index];
    if (!filterToUpdate) return;

    const newField = fields.find((f) => f.field === newValue.field);
    const oldField = fields.find((f) => f.field === filterToUpdate.field);

    if (!newField || !oldField) return;

    let value = filterToUpdate.value;
    let operator = newValue.operator;

    if (newField.type !== oldField.type) {
      operator = getDefaultOperator(newField.type);
      value = defineDefaultFilterValue(newField.type);
    }

    addOrReplaceByIndex({
      field: newValue.field as FieldPath<unknown>,
      operator: operator as OperatorsForType<never>,
      value: value as FilterValueFor<never>,
      options: newField.isCollection ? { quantifier: "some" } : undefined,
      replaceIndex: index,
    });
  };

  const onSelectOperator = (op: FilterOperator) => {
    if (!selectedFieldForAdd) return;

    const defaultDateRange = [
      new Date().toISOString(),
      new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString(),
    ];
    const defaultValue =
      selectedFieldForAdd.type === "date"
        ? defaultDateRange
        : selectedFieldForAdd.type === "number"
          ? [0, 0]
          : ["", ""];

    const prevOperatorIsBetween = operatorIsBetween(tempOperator);
    const newOperatorIsBetween = operatorIsBetween(op);

    setTempOperator(op);

    if (!operatorRequiresValue(op)) {
      setTempValue(null);
    } else if (!prevOperatorIsBetween && newOperatorIsBetween) {
      setTempValue(defaultValue);
    } else if (prevOperatorIsBetween && !newOperatorIsBetween) {
      setTempValue(defineDefaultFilterValue(selectedFieldForAdd.type, op));
    }
  };

  const handleRemoveFilter = (index: number) => {
    removeFilter(index);
  };

  const canAddFilter = React.useMemo(() => {
    if (!selectedFieldForAdd) return false;
    return isValidOperatorForType(tempValue, tempOperator);
  }, [tempValue, tempOperator, selectedFieldForAdd]);

  const STEP_VALUE_ADD_FILTER_BUTTON_DISABLED =
    !canAddFilter || tempValue === null || tempValue === "";

  return (
    <div className="flex flex-wrap items-center gap-2">
      {filterValues.map((filter, index) => (
        <FilterRow
          key={`${filter.field}-${index}`}
          fields={fields}
          value={filter}
          onChange={(newValue) => handleUpdateFilterDebounced(index, newValue)}
          onSelectField={(newValue) => handleSelectField(index, newValue)}
          onRemove={() => handleRemoveFilter(index)}
          usedFields={usedFields}
        />
      ))}
      <div className="flex items-center gap-2">
        {filterValues.length > 0 && (
          <Button
            variant="outline"
            size="sm"
            className="h-8 gap-1.5 bg-transparent"
            onClick={clearFilters}
          >
            <X className="h-4 w-4" />
          </Button>
        )}
        <Popover
          open={addFilterStep !== null}
          onOpenChange={(open) => !open && handleCancelAddFilter()}
        >
          <PopoverTrigger asChild>
            <Button
              variant="outline"
              size="sm"
              className="h-8 gap-1.5 bg-transparent"
              disabled={!HAS_FIELDS_REMAINING}
              onClick={() => setAddFilterStep("field")}
            >
              {filterValues.length === 0 ? (
                <>
                  <ListFilter className="h-4 w-4" />
                  Add Filter
                </>
              ) : (
                <ListFilter className="h-4 w-4" />
              )}
            </Button>
          </PopoverTrigger>
          <PopoverContent
            className={cn(
              addFilterStep === "field" ? "p-0" : "min-w-64 p-3",
              "bg-card w-fit"
            )}
            align="start"
          >
            {addFilterStep === "field" ? (
              <>
                <div className="p-2 border-b border-border">
                  <div className="relative">
                    <Search className="absolute left-2 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      placeholder="Search fields..."
                      value={search}
                      onChange={(e) => setSearch(e.target.value)}
                      className="h-8 pl-8"
                    />
                  </div>
                </div>
                <div className="max-h-60 overflow-y-auto p-1">
                  {filteredRemainingFields.map((field) => (
                    <button
                      key={field.field}
                      onClick={() => handleSelectFieldForAdd(field)}
                      className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent"
                    >
                      <span className="text-muted-foreground">
                        {TYPE_ICONS[field.type]}
                      </span>
                      <span className="flex-1 text-left">
                        {field.fieldLabel}
                      </span>
                    </button>
                  ))}
                  {filteredRemainingFields.length === 0 && (
                    <div className="py-6 text-center text-sm text-muted-foreground">
                      {search
                        ? "No fields found"
                        : "All fields are already in use"}
                    </div>
                  )}
                </div>
              </>
            ) : addFilterStep === "value" && selectedFieldForAdd ? (
              <div className="space-y-3">
                <div className="flex items-center gap-2 pb-2 border-b">
                  <span className="text-muted-foreground">
                    {TYPE_ICONS[selectedFieldForAdd.type]}
                  </span>
                  <span className="font-medium text-foreground text-sm">
                    {selectedFieldForAdd.fieldLabel}
                  </span>
                </div>

                <div className="flex items-center gap-2 ">
                  <div className="space-y-2 h-7">
                    <FilterOperatorSelector
                      type={selectedFieldForAdd.type}
                      isNullable={selectedFieldForAdd.isNullable}
                      selectedOperator={tempOperator}
                      onSelect={onSelectOperator}
                    />
                  </div>

                  {operatorRequiresValue(tempOperator) && (
                    <div className="space-y-2 flex-1 h-7">
                      {selectedFieldForAdd.type === "date" ? (
                        <FilterDateValue
                          operator={tempOperator}
                          value={tempValue as string | [string, string] | null}
                          onChange={setTempValue}
                        />
                      ) : selectedFieldForAdd.type === "boolean" ? (
                        <FilterBooleanValue
                          value={tempValue as boolean | null}
                          onChange={setTempValue}
                        />
                      ) : (
                        <FilterValueSelector
                          filter={selectedFieldForAdd}
                          operator={tempOperator}
                          value={tempValue as string | string[]}
                          onChange={setTempValue}
                        />
                      )}
                    </div>
                  )}
                </div>

                <div className="flex gap-2 pt-2">
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-7 flex-1 text-xs"
                    onClick={handleCancelAddFilter}
                  >
                    Cancel
                  </Button>
                  <Button
                    size="sm"
                    className="h-7 flex-1 text-xs"
                    disabled={STEP_VALUE_ADD_FILTER_BUTTON_DISABLED}
                    onClick={handleConfirmAddFilter}
                  >
                    Add Filter
                  </Button>
                </div>
              </div>
            ) : null}
          </PopoverContent>
        </Popover>
      </div>
    </div>
  );
}

"use client";

import { X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { FilterFieldSelector } from "./filter-field-selector";
import { FilterOperatorSelector } from "./filter-operator-selector";
import { FilterValueSelector } from "./filter-value-selector";
import { FilterDateValue } from "./filter-date-value";
import { FilterBooleanValue } from "./filter-boolean-value";
import {
  type QueryFilter,
  type FilterValue,
  type FilterOperator,
  getDefaultOperator,
  operatorRequiresValue,
  operatorIsBetween,
  defineDefaultFilterValue,
} from "@/lib/filter-utils";

interface FilterRowProps {
  fields: QueryFilter[];
  value: FilterValue;
  onSelectField: (value: FilterValue) => void;
  onChange: (value: FilterValue) => void;
  onRemove: () => void;
  usedFields?: string[];
}

export function FilterRow({
  fields,
  value,
  onChange,
  onRemove,
  onSelectField,
  usedFields = [],
}: FilterRowProps) {
  const currentField = fields.find((f) => f.field === value.field);
  const type = currentField?.type || "string";

  const handleFieldChange = (field: QueryFilter) => {
    onSelectField({
      field: field.field,
      operator: getDefaultOperator(field.type),
      value: null,
    });
  };

  const handleOperatorChange = (operator: FilterOperator) => {
    const prevOperatorIsBetween = operatorIsBetween(value.operator);
    const newOperatorIsBetween = operatorIsBetween(operator);

    let newValue = value.value;

    if (!operatorRequiresValue(operator)) {
      newValue = null;
    } else if (!prevOperatorIsBetween && newOperatorIsBetween) {
      // Switching to between operator
      newValue =
        type === "number" ? [0, 0] : type === "date" ? ["", ""] : ["", ""];
    } else if (prevOperatorIsBetween && !newOperatorIsBetween) {
      // Switching from between operator
      newValue = defineDefaultFilterValue(type, operator);
    }

    onChange({
      ...value,
      operator,
      value: newValue,
    });
  };

  const handleValueChange = (newValue: FilterValue["value"]) => {
    onChange({
      ...value,
      value: newValue,
    });
  };

  const renderValueInput = () => {
    if (!operatorRequiresValue(value.operator)) {
      return null;
    }

    if (type === "date") {
      return (
        <FilterDateValue
          operator={value.operator}
          value={value.value as string | [string, string] | null}
          onChange={handleValueChange}
        />
      );
    }

    if (type === "boolean") {
      return (
        <FilterBooleanValue
          value={value.value as boolean | null}
          onChange={handleValueChange}
        />
      );
    }

    if (currentField) {
      return (
        <FilterValueSelector
          filter={currentField}
          operator={value.operator}
          value={value.value as string | string[]}
          onChange={handleValueChange}
        />
      );
    }

    return null;
  };

  return (
    <div className="group flex items-center gap-1.5 rounded-md border border-border bg-card p-1">
      <FilterFieldSelector
        fields={fields}
        selectedField={value.field}
        onSelect={handleFieldChange}
        usedFields={usedFields}
      />
      <FilterOperatorSelector
        type={type}
        isNullable={currentField?.isNullable}
        selectedOperator={value.operator}
        onSelect={handleOperatorChange}
      />
      {renderValueInput()}
      <Button
        variant="ghost"
        size="sm"
        className="h-7 w-7 p-0 text-muted-foreground hover:text-foreground ml-auto"
        onClick={onRemove}
      >
        <X className="h-4 w-4" />
      </Button>
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, Search, X, Plus, CircleDashed } from "lucide-react";
import { Popover, PopoverContent, PopoverTrigger } from "../ui/popover";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import type { QueryFilter, FilterOperator } from "../../lib/filter-utils";
import {
  operatorSupportsMultipleValues,
  operatorIsBetween,
} from "../../lib/filter-utils";

interface FilterValueSelectorProps {
  filter: QueryFilter;
  operator: FilterOperator;
  value:
    | string
    | string[]
    | number
    | number[]
    | [string, string]
    | [number, number];
  onChange: (
    value:
      | string
      | string[]
      | number
      | number[]
      | [string, string]
      | [number, number]
  ) => void;
}

export function FilterValueSelector({
  filter,
  operator,
  value,
  onChange,
}: FilterValueSelectorProps) {
  const [open, setOpen] = React.useState(false);
  const [search, setSearch] = React.useState("");
  const isMultiple = operatorSupportsMultipleValues(operator);
  const isBetween = operatorIsBetween(operator);
  const hasOptions = filter.options && filter.options.length > 0;

  const selectedValues: string[] = React.useMemo(() => {
    if (isBetween || !value) return [];
    if (Array.isArray(value)) return value.map(String);
    return [String(value)];
  }, [value, isBetween]);

  const filteredOptions =
    filter.options?.filter((opt) =>
      opt.label.toLowerCase().includes(search.toLowerCase())
    ) || [];

  const handleSelect = (optionValue: string) => {
    if (isMultiple) {
      const newValues = selectedValues.includes(optionValue)
        ? selectedValues.filter((v) => v !== optionValue)
        : [...selectedValues, optionValue];
      onChange(newValues);
    } else {
      onChange(optionValue);
      setOpen(false);
    }
  };

  const handleRemoveValue = (optionValue: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (isMultiple) {
      onChange(selectedValues.filter((v) => v !== optionValue));
    } else {
      onChange("");
    }
  };

  const getOptionLabel = (val: string) => {
    return filter.options?.find((opt) => opt.value === val)?.label || val;
  };

  const getOptionIcon = (val: string) => {
    return (
      filter.options?.find((opt) => opt.value === val)?.icon ?? <CircleDashed />
    );
  };

  if (isBetween && !hasOptions) {
    const betweenValue: [string | number, string | number] =
      Array.isArray(value) && value.length === 2
        ? [value[0], value[1]]
        : ["", ""];
    const fromValue = betweenValue[0];
    const toValue = betweenValue[1];

    return (
      <div className="flex items-center gap-1">
        <Input
          type={filter.type === "number" ? "number" : "text"}
          placeholder="From..."
          value={fromValue ?? ""}
          onChange={(e) => {
            const newFrom =
              filter.type === "number"
                ? e.target.value
                  ? Number(e.target.value)
                  : 0
                : e.target.value;
            onChange([newFrom, toValue] as [number, number] | [string, string]);
          }}
          className="h-7 w-24 text-sm"
        />
        <span className="text-xs text-muted-foreground">to</span>
        <Input
          type={filter.type === "number" ? "number" : "text"}
          placeholder="To..."
          value={toValue ?? ""}
          onChange={(e) => {
            const newTo =
              filter.type === "number"
                ? e.target.value
                  ? Number(e.target.value)
                  : 0
                : e.target.value;
            onChange([fromValue, newTo] as [number, number] | [string, string]);
          }}
          className="h-7 w-24 text-sm"
        />
      </div>
    );
  }

  if (hasOptions) {
    const renderDisplayContent = () => {
      if (selectedValues.length === 0) {
        return (
          <div className="flex items-center gap-1 text-muted-foreground">
            <Plus className="h-3.5 w-3.5" />
            <span className="text-xs">Selecionar</span>
          </div>
        );
      }

      if (selectedValues.length === 1) {
        const val = selectedValues[0];
        return (
          <div className="flex items-center gap-1">
            {getOptionIcon(val)}
            <span className="text-xs">{getOptionLabel(val)}</span>
            <div
              onClick={(e) => handleRemoveValue(val, e)}
              role="button"
              className="ml-0.5 rounded-full hover:bg-muted-foreground/20"
            >
              <X className="h-3 w-3" />
            </div>
          </div>
        );
      }

      return (
        <div className="flex items-center gap-1.5">
          <div className="flex items-center -space-x-2.5">
            {selectedValues.slice(0, 3).map((val) => {
              const icon = getOptionIcon(val);
              return icon ? (
                <div
                  key={val}
                  className="rounded-full border bg-background p-0.5"
                >
                  <span className="text-[10px]">{icon}</span>
                </div>
              ) : null;
            })}
          </div>
          <span className="text-xs font-medium truncate">
            {selectedValues.length} selected
            {selectedValues.length > 1 ? "s" : ""}
          </span>
        </div>
      );
    };

    return (
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            variant="secondary"
            size="sm"
            className="h-7 gap-1 pl-1.5 pr-1.5 text-xs font-normal hover:bg-secondary/80"
          >
            {renderDisplayContent()}
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-52 p-0" align="start">
          <div className="p-2 border-b border-border">
            <div className="relative">
              <Search className="absolute left-2 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Search options..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="h-8 pl-8"
              />
            </div>
          </div>
          <div className="max-h-60 overflow-y-auto p-1">
            {filteredOptions.map((option) => (
              <button
                key={option.value}
                onClick={() => handleSelect(option.value)}
                className={cn(
                  "flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent",
                  selectedValues.includes(option.value) && "bg-accent"
                )}
              >
                {option.icon && (
                  <span className="text-muted-foreground">{option.icon}</span>
                )}
                <span className="flex-1 text-left">{option.label}</span>
                {selectedValues.includes(option.value) && (
                  <Check className="h-4 w-4" />
                )}
              </button>
            ))}
            {filteredOptions.length === 0 && (
              <div className="py-6 text-center text-sm text-muted-foreground">
                No options found
              </div>
            )}
          </div>
        </PopoverContent>
      </Popover>
    );
  }

  // Simple input for non-array values
  const simpleValue = Array.isArray(value) ? "" : (value ?? "");

  return (
    <Input
      type={filter.type === "number" ? "number" : "text"}
      placeholder="Enter value..."
      defaultValue={simpleValue}
      onChange={(e) => {
        const newValue =
          filter.type === "number"
            ? e.target.value
              ? Number(e.target.value)
              : 0
            : e.target.value;
        onChange(newValue);
      }}
      className="h-7 w-32 text-sm"
    />
  );
}

"use client";

import * as React from "react";
import { Check, Search, Type, Hash, Calendar, ToggleLeft } from "lucide-react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import type { QueryFilter, FilterType } from "@/lib/filter-utils";

interface FilterFieldSelectorProps {
  fields: QueryFilter[];
  selectedField: string;
  onSelect: (field: QueryFilter) => void;
  usedFields?: string[];
}

const TYPE_ICONS: Record<FilterType, React.ReactNode> = {
  string: <Type className="h-4 w-4" />,
  number: <Hash className="h-4 w-4" />,
  date: <Calendar className="h-4 w-4" />,
  boolean: <ToggleLeft className="h-4 w-4" />,
};

export function FilterFieldSelector({
  fields,
  selectedField,
  onSelect,
  usedFields = [],
}: FilterFieldSelectorProps) {
  const [open, setOpen] = React.useState(false);
  const [search, setSearch] = React.useState("");

  const selectedFieldData = fields.find((f) => f.field === selectedField);

  const availableFields = fields.filter(
    (field) =>
      field.field === selectedField || !usedFields.includes(field.field)
  );

  const filteredFields = availableFields.filter((field) =>
    field.fieldLabel.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="ghost"
          size="sm"
          className="h-7 gap-1.5 px-2 text-muted-foreground hover:text-foreground"
        >
          {selectedFieldData && TYPE_ICONS[selectedFieldData.type]}
          <span>{selectedFieldData?.fieldLabel || "Select field"}</span>
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-52 p-0" align="start">
        <div className="p-2 border-b border-border">
          <div className="relative">
            <Search className="absolute left-2 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Search fields..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="h-8 pl-8"
            />
          </div>
        </div>
        <div className="max-h-60 overflow-y-auto p-1">
          {filteredFields.map((field) => (
            <button
              key={field.field}
              onClick={() => {
                onSelect(field);
                setOpen(false);
                setSearch("");
              }}
              className={cn(
                "flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent",
                selectedField === field.field && "bg-accent"
              )}
            >
              <span className="text-muted-foreground">
                {TYPE_ICONS[field.type]}
              </span>
              <span className="flex-1 text-left">{field.fieldLabel}</span>
              {selectedField === field.field && (
                <Check className="h-4 w-4 text-foreground" />
              )}
            </button>
          ))}
          {filteredFields.length === 0 && (
            <div className="py-6 text-center text-sm text-muted-foreground">
              No fields found
            </div>
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}

